"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/hooks/use-auth";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { CheckCircle, XCircle, Clock } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface Post {
  _id?: string;
  clientId?: string;
  title: string;
  platform: string;
  caption: string;
  scheduledDate: string;
  scheduledTime?: string;
  status: string;
  approvalStatus?: "Pending" | "Approved" | "Rejected";
  createdBy?: string;
  notes?: string;
}

export default function ClientPlannerPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [rejectionReason, setRejectionReason] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState<Record<string, boolean>>({});

  useEffect(() => {
    if (!user || user.role !== "client") return;

    const fetchPosts = async () => {
      try {
        setLoading(true);
        const token = typeof window !== "undefined" ? localStorage.getItem("auth_token") : null;
        const headers: Record<string, string> = { "Content-Type": "application/json" };
        if (token) headers["Authorization"] = `Bearer ${token}`;

        const res = await fetch("/api/social-media-planner", { headers });
        if (!res.ok) throw new Error("Failed to fetch posts");

        const data: any[] = await res.json();
        // Filter by client ID
        const clientPosts = Array.isArray(data)
          ? data.filter((p) => p.clientId === user.clientId)
          : [];
        setPosts(clientPosts);
      } catch (err) {
        console.error("Failed to load posts", err);
        setPosts([]);
      } finally {
        setLoading(false);
      }
    };

    fetchPosts();
  }, [user]);

  const handleApprove = async (postId: string) => {
    try {
      setIsSubmitting((prev) => ({ ...prev, [postId]: true }));
      const token = typeof window !== "undefined" ? localStorage.getItem("auth_token") : null;
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
      };
      if (token) headers["Authorization"] = `Bearer ${token}`;

      const res = await fetch(`/api/social-media-planner/${postId}`, {
        method: "PATCH",
        headers,
        body: JSON.stringify({
          approvalStatus: "Approved",
        }),
      });

      if (!res.ok) throw new Error("Failed to approve post");

      toast({
        title: "Post Approved ✅",
        description: "Your team will be notified.",
      });

      // Refresh posts
      const allRes = await fetch("/api/social-media-planner", { headers });
      const data = await allRes.json();
      const clientPosts = Array.isArray(data)
        ? data.filter((p) => p.clientId === user?.clientId)
        : [];
      setPosts(clientPosts);
    } catch (err) {
      console.error("Error approving post", err);
      toast({
        title: "Error",
        description: "Failed to approve post",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting((prev) => ({ ...prev, [postId]: false }));
    }
  };

  const handleReject = async (postId: string) => {
    const reason = rejectionReason[postId];
    if (!reason.trim()) {
      toast({
        title: "Required",
        description: "Please provide a reason for rejection",
        variant: "destructive",
      });
      return;
    }

    try {
      setIsSubmitting((prev) => ({ ...prev, [postId]: true }));
      const token = typeof window !== "undefined" ? localStorage.getItem("auth_token") : null;
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
      };
      if (token) headers["Authorization"] = `Bearer ${token}`;

      const res = await fetch(`/api/social-media-planner/${postId}`, {
        method: "PATCH",
        headers,
        body: JSON.stringify({
          approvalStatus: "Rejected",
          rejectionReason: reason,
        }),
      });

      if (!res.ok) throw new Error("Failed to reject post");

      toast({
        title: "Post Rejected ❌",
        description: "Your team will be notified with the reason.",
      });

      // Clear rejection reason
      setRejectionReason((prev) => {
        const newState = { ...prev };
        delete newState[postId];
        return newState;
      });

      // Refresh posts
      const allRes = await fetch("/api/social-media-planner", { headers });
      const data = await allRes.json();
      const clientPosts = Array.isArray(data)
        ? data.filter((p) => p.clientId === user?.clientId)
        : [];
      setPosts(clientPosts);
    } catch (err) {
      console.error("Error rejecting post", err);
      toast({
        title: "Error",
        description: "Failed to reject post",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting((prev) => ({ ...prev, [postId]: false }));
    }
  };

  if (!user || user.role !== "client") {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Card className="border-2 border-black">
          <CardHeader>
            <CardTitle>Access Denied</CardTitle>
          </CardHeader>
          <CardContent>
            <p>This page is only accessible to clients.</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background font-headline p-6 space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-4xl font-black tracking-tighter">Social Media Planner</h1>
        <p className="text-muted-foreground mt-1">View your scheduled social media posts</p>
      </div>

      {/* Posts Grid */}
      <div>
        {loading ? (
          <div className="text-center text-muted-foreground">Loading posts...</div>
        ) : posts.length === 0 ? (
          <Card className="border-2 border-black">
            <CardContent className="pt-6 text-center">
              <div className="text-4xl mb-2">📋</div>
              <p className="font-bold">No posts scheduled yet</p>
              <p className="text-sm text-muted-foreground">Your scheduled posts will appear here</p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {posts.map((post) => (
              <Card key={post._id} className="border-2 border-black shadow-[2px_2px_0px_0px_rgba(0,0,0,1)]">
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between">
                    <CardTitle className="text-sm line-clamp-2">{post.title || "Untitled"}</CardTitle>
                    {post.platform && (
                      <Badge variant="outline" className="border-black font-bold ml-2">
                        {post.platform}
                      </Badge>
                    )}
                  </div>
                </CardHeader>
                <CardContent className="space-y-3">
                  <p className="text-sm text-muted-foreground line-clamp-3">{post.description || post.caption || "-"}</p>
                  {post.scheduledDate && (
                    <div className="text-xs text-muted-foreground">
                      📅 {new Date(post.scheduledDate).toLocaleDateString()}
                    </div>
                  )}
                  {post.status && (
                    <Badge className="bg-primary text-primary-foreground font-bold">
                      {post.status}
                    </Badge>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>

      {/* Info Card */}
      <Card className="border-2 border-black bg-primary/5">
        <CardContent className="pt-6">
          <p className="text-sm">
            <span className="font-bold">💡 Note:</span> This is a read-only view of your scheduled posts. Your team manages all content scheduling.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}
